#ifndef TESTS_H
#define TESTS_H

#include <stdbool.h>  // bool
#include <stdio.h>    // puts
#include <unity.h>

// Set by main() when the runner is started with -l.
extern bool tests_list_only;

// Like Unity's RUN_TEST, but honours the command-line options:
//   -l          list the tests
//   -f NAME     run only the tests whose name contains NAME
//   -x NAME     skip the tests whose name contains NAME
// (Unity applies these filters only in runners generated by its Ruby script.)
// UnitySetTestFile: a failure is reported in the file of the test, not in
// tests/main.c where UNITY_BEGIN() was called.
#define RUN(test)                        \
    do {                                 \
        UnitySetTestFile(__FILE__);      \
        Unity.CurrentTestName = #test;   \
        if (tests_list_only) {           \
            puts(#test);                 \
        } else if (UnityTestMatches()) { \
            RUN_TEST(test);              \
        }                                \
    } while (0)

// One function per module, defined in tests/<module>_test.c, which runs the
// tests of that module. main() calls each of them.
void error_tests(void);
void example_tests(void);

#endif
